- github_project_linkages {"type": "array", "uniqueItems": true, "description": "1つのtask/issueを複数GitHub Projects v2へ関連付ける永続linkage。field valueのupdatedAtは競合hintに使い、削除/欠落/renameも扱うcanonical 3-way baseはfield_snapshotとする。Beads mirrorはviewer-onlyで本linkageのcustom-field同期対
- pull_request_linkages {"type": "array", "uniqueItems": true, "items": {"type": "object", "additionalProperties": false, "required": ["repo", "pr_number", "url", "base_branch", "head_branch", "state", "merged_at", "merge_commit_sha", "linked_at", "closing_referen
- execution_contexts {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["worktree_id", "branch", "base_branch", "head_sha", "state", "lease_acquired_at", "last_seen_at", "released_at"], "properties": {"worktree_id": {"type
- completion_evidence {"type": "object", "additionalProperties": false, "required": ["policy", "status", "source", "completed_at", "reconciled_at", "evidence_refs"], "properties": {"policy": {"type": "string", "enum": ["manual", "linked_pr_merged_all", "linked_p
- implementation_readiness {"type": "object", "required": ["status", "missing_sections", "checked_at"], "properties": {"status": {"type": "string", "enum": ["complete", "incomplete", "not_applicable"]}, "missing_sections": {"type": "array", "items": {"type": "string"

